--
-- Acionadores `Proposta`
--
DELIMITER $$
CREATE TRIGGER `tgr_delete_historico` BEFORE DELETE ON `Proposta` FOR EACH ROW BEGIN
                            DELETE FROM Historico
                            WHERE codigoProposta = OLD.codigoProposta;
                        END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tgr_insert_historico` BEFORE UPDATE ON `Proposta` FOR EACH ROW BEGIN
    IF (NEW.revisao <> OLD.revisao) THEN
            codigoProposta,
            codigoPropostaSuper,
            idCliente,
            userUsuarioResponsavel,
            tipoContrato,
            titulo,
            dataSolicitacao,
            dataEmissao,
            dataValidade,
            dataAtualizacao,
            situacao,
            expectativa,
            tipoPrincipal,
            prazoEmMeses,
            observacao,
            valorSubcontratacao,
            valorMobilizacao,
            avaliacaoRisco,
        valorDesconto,
        codigoPropostaAntigo,
        revisao
        )
        VALUES
        (
            OLD.codigoProposta,
            OLD.codigoPropostaSuper,
            OLD.idCliente,
            OLD.userUsuarioResponsavel,
            OLD.tipoContrato,
            OLD.titulo,
            OLD.dataSolicitacao,
            OLD.dataEmissao,
            OLD.dataValidade,
            OLD.dataAtualizacao,
            OLD.situacao,
            OLD.expectativa,
            OLD.tipoPrincipal,
            OLD.prazoEmMeses,
            OLD.observacao,
            OLD.valorSubcontratacao,
            OLD.valorMobilizacao,
            OLD.avaliacaoRisco,
        OLD.valorDesconto,
        OLD.codigoPropostaAntigo,
        OLD.revisao
        );
    END IF;
 END
$$
DELIMITER ;

